def proof(*keys):
    return [dict(evidence_file='native-evidence/friendsandfoes.json',witness_id=W[k]['id'],entry=W[k]['entry'],methods=sorted({m['name'] for m in W[k].get('methods',[])})) for k in keys]

def c(primitive,formula,numbers=None,binary=None,relation='CUSTOM'):
    return dict(primitive=primitive,formula=formula,numerical_parameters=numbers or {},binary_parameters=binary or [],vanilla_relation=relation)

def add(key,name,kind,actual,closest,difference,components,keys,state='No new target capability; native state described in behavior.',registry=None):
    implementation=proof(*keys)
    for component in components:component['implementation']=implementation
    e=dict(id='friendsandfoes:'+key,mod_key='friendsandfoes',display_name=name,primary_classification=kind,actual_behavior=actual,human_summary=actual,
        registry_ids=registry or [],implementation=implementation,closest_vanilla_equivalent=closest,vanilla_similarities='Exact shared primitives, eligibility and differences are recorded per component and in native_behavior.',vanilla_differences=difference,
        components=components,numerical_parameters={k:v for x in components for k,v in x['numerical_parameters'].items()},binary_parameters=[v for x in components for v in x['binary_parameters']],
        scalable_parameter_candidates=[dict(primitive=x['primitive'],parameters=list(x['numerical_parameters']),meaning='Observation only; no Stage, calibration or eligibility proposal.') for x in components if x['numerical_parameters']],
        custom_state=state,delivery_paths=[],primary_test_source=None,alternate_sources=[],inspection_status='VERIFIED',unresolved_ambiguities=[],reference_files=REFERENCES)
    E.append(e);return e

def p(key,rows,labels,source,setup,keys,fixture):
    row=dict(id='friendsandfoes:'+key,mod_key='friendsandfoes',status='VERIFIED',labels=labels,effect_ids=[e['id'] for e in rows],primary_source=source,setup=setup,implementation=proof(*keys),fixture_family=fixture)
    P.append(row)
    for e in rows:
        e['delivery_paths'].append(row['id'])
        if e['primary_test_source'] is None:e['primary_test_source']=source
        elif e['primary_test_source']!=source and source not in e['alternate_sources']:e['alternate_sources'].append(source)

