def draft():
    obj=dict(schema='tno.external_effects.partial_draft.v1',baseline=BASELINE,mod_key='friendsandfoes',status='PARTIAL',checkpoint='R2e-draft',starting_sha=START,semantic_coverage_complete=False,promoted_to_catalog=False,effects=E,paths=P,remaining=['Finalize coverage/exclusions, comparison claims and exact source cases; validate then promote.'],**boundary_flags())
    import copy
    obj=copy.deepcopy(obj)
    for e in obj['effects']:e.update(inspection_status='DRAFT',unresolved_ambiguities=None,pending=obj['remaining'])
    for p in obj['paths']:p['status']='DRAFT'
    write_json(OUT/'partial-drafts/friendsandfoes-r2e-draft.json',obj)
    print(len(E),'draft packages',len(P),'paths')

if __name__=='__main__':draft()
